import React, { useState, useEffect } from 'react';
import { DollarSign, Users, ShoppingBag, TrendingUp, ArrowUp, ArrowDown, TrendingDown, Zap } from 'lucide-react';

const StatsCards = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const stats = [
    { 
      title: 'Revenu total', 
      value: '$54,231', 
      change: '+12.5%', 
      icon: <DollarSign className="h-5 w-5" />, 
      color: 'primary', 
      trend: 'up',
      description: 'Ce mois'
    },
    { 
      title: 'Nouveaux utilisateurs', 
      value: '3,254', 
      change: '+8.2%', 
      icon: <Users className="h-5 w-5" />, 
      color: 'accent', 
      trend: 'up',
      description: '30 derniers jours'
    },
    { 
      title: 'Commandes', 
      value: '1,243', 
      change: '+5.7%', 
      icon: <ShoppingBag className="h-5 w-5" />, 
      color: 'secondary', 
      trend: 'up',
      description: 'Cette semaine'
    },
    { 
      title: 'Taux de conversion', 
      value: '3.42%', 
      change: '-1.2%', 
      icon: <TrendingUp className="h-5 w-5" />, 
      color: 'warning', 
      trend: 'down',
      description: 'Comparaison mensuelle'
    },
  ];

  const getGradient = (color) => {
    const gradients = {
      primary: 'from-primary-500/20 to-primary-600/10',
      accent: 'from-accent-500/20 to-accent-600/10',
      secondary: 'from-secondary-500/20 to-secondary-600/10',
      warning: 'from-warning-500/20 to-warning-600/10',
    };
    return gradients[color] || gradients.primary;
  };

  const getIconBg = (color) => {
    const backgrounds = {
      primary: 'bg-primary-100 dark:bg-primary-900/30',
      accent: 'bg-accent-100 dark:bg-accent-900/30',
      secondary: 'bg-secondary-100 dark:bg-secondary-900/30',
      warning: 'bg-warning-100 dark:bg-warning-900/30',
    };
    return backgrounds[color];
  };

  const getIconColor = (color) => {
    const colors = {
      primary: 'text-primary-600 dark:text-primary-400',
      accent: 'text-accent-600 dark:text-accent-400',
      secondary: 'text-secondary-600 dark:text-secondary-400',
      warning: 'text-warning-600 dark:text-warning-400',
    };
    return colors[color];
  };

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 lg:gap-6 mb-6 sm:mb-8">
      {stats.map((stat, index) => (
        <div 
          key={index}
          className={`relative bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl sm:rounded-2xl p-4 sm:p-6 shadow-lg border border-white/30 dark:border-neutral-800/50 overflow-hidden group hover:scale-[1.02] transition-all duration-300 animate-slide-up ${
            isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'
          }`}
          style={{
            transitionDelay: `${index * 100}ms`,
            animationDelay: `${index * 100}ms`,
          }}
        >
          {/* Effet de brillance sur hover */}
          <div className={`absolute inset-0 bg-gradient-to-br ${getGradient(stat.color)} opacity-0 group-hover:opacity-100 transition-opacity duration-500`} />

          {/* Bordure animée */}
          <div className={`absolute inset-0 rounded-xl sm:rounded-2xl border-2 border-transparent group-hover:border-${stat.color}-500/20 transition-all duration-300`} />

          <div className="relative z-10">
            <div className="flex items-start justify-between mb-4 gap-3">
              <div className={`p-2 sm:p-3 rounded-lg sm:rounded-xl ${getIconBg(stat.color)} ${getIconColor(stat.color)} transition-all duration-300 group-hover:scale-110`}>
                {stat.icon}
              </div>

              <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-xs font-semibold ${
                stat.trend === 'up' 
                  ? 'bg-accent-50 text-accent-700 dark:bg-accent-900/30 dark:text-accent-400' 
                  : 'bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-400'
              } transition-all duration-300`}>
                {stat.trend === 'up' ? (
                  <ArrowUp className="h-3 w-3" />
                ) : (
                  <ArrowDown className="h-3 w-3" />
                )}
                <span>{stat.change}</span>
              </div>
            </div>

            <h3 className="text-xl sm:text-2xl font-bold text-neutral-900 dark:text-white mb-1 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors duration-300">
              {stat.value}
            </h3>

            <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-2 font-medium">
              {stat.title}
            </p>

            <p className="text-xs text-neutral-500 dark:text-neutral-500">
              {stat.description}
            </p>

            {/* Barre de progression */}
            <div className="mt-4">
              <div className="flex justify-between text-xs text-neutral-500 dark:text-neutral-400 mb-1">
                <span>Progression</span>
                <span>{stat.trend === 'up' ? '↑' : '↓'}</span>
              </div>
              <div className="h-1 w-full bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
                <div 
                  className={`h-full rounded-full transition-all duration-1000 ${
                    stat.trend === 'up' 
                      ? 'bg-accent-500' 
                      : 'bg-red-500'
                  }`}
                  style={{ 
                    width: stat.trend === 'up' ? '75%' : '30%',
                    animation: stat.trend === 'up' ? 'pulseGentle 2s ease-in-out infinite' : 'none'
                  }}
                />
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default StatsCards;
